actions.script:
startedRequestNames = [];
failedRequestNames = [];
if (System.getProperty("device_gateway_restore_subscriptions") === "false") return;
const state = ec.service.sync().name("moqui.device.gateway.SubscriptionServices.get#SubscriptionState")
    .parameters({claimStartup: true}).call();
if (ec.message.hasError()) return;
let names = state.droppedRequestNames || [];
if (state.startupClaimed) {
    const active = new Set(state.activeRequestNames || []);
    const types = ['DrtSubscribe', 'DrtEvent', 'DrtStateChange', 'DrtCyclic'];
    names = (ec.entity.find("moqui.device.DeviceRequest").conditionDate("fromDate", "thruDate").list() || [])
        .filter(r => types.includes(r.requestTypeEnumId) && (r.runServiceName || '').startsWith('moqui.device.gateway.'))
        .map(r => r.requestName)
        .filter(n => !active.has(n));
}
for (const requestName of names) {
    try {
        ec.service.sync().name("moqui.device.DeviceServices.run#DeviceRequest")
            .parameters({requestName: requestName}).call();
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString());
        startedRequestNames.push(requestName);
    } catch (e) {
        failedRequestNames.push(requestName);
        ec.logger.warn(`Device gateway subscription ${requestName} did not start: ${e.message || e}`);
        ec.message.clearErrors();
    }
}
if (startedRequestNames.length || failedRequestNames.length) {
    ec.logger.info(`Device gateway subscriptions started: ${startedRequestNames.length}, failed: ${failedRequestNames.length}`);
}
